(2942972, 411555, 36619, '<td valign="top">love the title, it''s really a unique image!</td>', 'love the title, it''s really a unique image!', '2006-10-19 03:27:32.000000', NULL, 1),
(2942993, 412173, 46598, '<td valign="top">Cool effect! I just wish there was another one to bridge teh gap between the first and secodn light.<br/> <br/>Like the photo!</td>', 'Cool effect! I just wish there was another one to bridge teh gap between the first and secodn light. Like the photo!', '2006-10-19 03:57:59.000000', NULL, 1),
(2943002, 411872, 66201, '<td valign="top">I wish that this had been slightly bigger: it could have great impact. Dot in the sun aura is distracting (a bird?) but otherwise I love the staurated colours: so difficult in a predominantly sky shot.</td>', 'I wish that this had been slightly bigger: it could have great impact. Dot in the sun aura is distracting (a bird?) but otherwise I love the staurated colours: so difficult in a predominantly sky shot.', '2006-10-19 04:04:36.000000', NULL, 1),
(2943003, 412986, 46598, '<td valign="top">beautiful use of the sun.</td>', 'beautiful use of the sun.', '2006-10-19 04:04:39.000000', NULL, 1),
(2943004, 412399, 66201, '<td valign="top">weird... the candles look like stylised breasts??</td>', 'weird... the candles look like stylised breasts??', '2006-10-19 04:05:26.000000', NULL, 1),
(2943005, 411507, 66201, '<td valign="top">Just glorious.</td>', 'Just glorious.', '2006-10-19 04:05:50.000000', NULL, 1),
(2943007, 413224, 66201, '<td valign="top">great minimalist shot.</td>', 'great minimalist shot.', '2006-10-19 04:07:23.000000', NULL, 1),
(2943008, 413335, 46598, '<td valign="top">Really interesting use of the light. I like the meeting of the two kinds of light lighting (pure white) and the light from the docs (yellowish). It''s a nice contract. I''m a bit bothered by the post right in front of the camera though... maybe moving a step forward would have helped. Nice shot still.</td>', 'Really interesting use of the light. I like the meeting of the two kinds of light lighting (pure white) and the light from the docs (yellowish). It''s a nice contract. I''m a bit bothered by the post right in front of the camera though... maybe moving a step forward would have helped. Nice shot still.', '2006-10-19 04:08:05.000000', NULL, 1),
(2943011, 412950, 66201, '<td valign="top">would hav liked to have more sharpness/focu. Interesting colour saturation.</td>', 'would hav liked to have more sharpness/focu. Interesting colour saturation.', '2006-10-19 04:08:47.000000', NULL, 1),
(2943015, 412984, 66201, '<td valign="top">unquestionably the best picture in this challenge!! 10.</td>', 'unquestionably the best picture in this challenge!! 10.', '2006-10-19 04:09:29.000000', NULL, 1),
