(2944231, 411781, 9504, '<td valign="top">Excellent photo.  Very nice.</td>', 'Excellent photo.  Very nice.', '2006-10-19 14:44:53.000000', NULL, 1),
(2944235, 412041, 58610, '<td valign="top">The picture seems skewed - not centered. I would like it better if it were more symetrical. I like the way the light is playing off the columns and chairs on the right hand side.</td>', 'The picture seems skewed - not centered. I would like it better if it were more symetrical. I like the way the light is playing off the columns and chairs on the right hand side.', '2006-10-19 14:45:39.000000', NULL, 1),
(2944236, 411888, 9504, '<td valign="top">Excellent execution!  Superb.  Great reflections. 9</td>', 'Excellent execution!  Superb.  Great reflections. 9', '2006-10-19 14:46:05.000000', NULL, 1),
(2944238, 412938, 9504, '<td valign="top">Well done.  Great job. 9</td>', 'Well done.  Great job. 9', '2006-10-19 14:46:23.000000', NULL, 1),
(2944271, 413254, 3102, '<td valign="top">Looks very Neil Shapiro-esque -- beautiful!  The swirling leaves really make this a unique shot!</td>', 'Looks very Neil Shapiro-esque -- beautiful!  The swirling leaves really make this a unique shot!', '2006-10-19 14:59:10.000000', NULL, 1),
(2944277, 413251, 3102, '<td valign="top">I''m wondering if those are the buildings that are outlined and lit up at night?  I was driving through Philadelphia a few weeks ago, and I''m fairly sure I drove right by there.  Neat spot!</td>', 'I''m wondering if those are the buildings that are outlined and lit up at night?  I was driving through Philadelphia a few weeks ago, and I''m fairly sure I drove right by there.  Neat spot!', '2006-10-19 15:01:59.000000', NULL, 1),
(2944283, 413325, 3102, '<td valign="top">Looks GraphicFunkish to me!  Very interesting use of blurred lights.  As usual, I''ll look forward to seeing the details on how this was pulled off, since there''s no motion detectable in the body.</td>', 'Looks GraphicFunkish to me!  Very interesting use of blurred lights.  As usual, I''ll look forward to seeing the details on how this was pulled off, since there''s no motion detectable in the body.', '2006-10-19 15:04:13.000000', NULL, 1),
(2944300, 411863, 33947, '<td valign="top">The lighting is fantastic, but the composition is bit confusing. 5</td>', 'The lighting is fantastic, but the composition is bit confusing. 5', '2006-10-19 15:09:43.000000', NULL, 1),
(2944308, 412394, 65603, '<td valign="top">I love this as a person with severe insomnia, how true this pic is. I am curios as to how you made it.</td>', 'I love this as a person with severe insomnia, how true this pic is. I am curios as to how you made it.', '2006-10-19 15:13:08.000000', NULL, 1),
(2944321, 411997, 33947, '<td valign="top">I love the counterplay between the whitish glow of the plants in the foreground and the glow of the artifacts in the background. Do you know how you got the artifacts? I got them once like you did, and have never been able to duplicate them. Lovely, simple composition. 7</td>', 'I love the counterplay between the whitish glow of the plants in the foreground and the glow of the artifacts in the background. Do you know how you got the artifacts? I got them once like you did, and have never been able to duplicate them. Lovely, simple composition. 7', '2006-10-19 15:17:30.000000', NULL, 1),
(2944325, 413008, 33947, '<td valign="top">Fascinating lighting. Love the reflection fo color in the street. 6</td>', 'Fascinating lighting. Love the reflection fo color in the street. 6', '2006-10-19 15:19:31.000000', NULL, 1),
(2944329, 411074, 33947, '<td valign="top">I''m not sure I understand it, but I am fascinated by it. A 6 for creativity and positioning within the frame.</td>', 'I''m not sure I understand it, but I am fascinated by it. A 6 for creativity and positioning within the frame.', '2006-10-19 15:21:58.000000', NULL, 1),
