(2944962, 413266, 63369, '<td valign="top">nice idea on the angle love the colors</td>', 'nice idea on the angle love the colors', '2006-10-19 19:17:09.000000', NULL, 1),
(2944966, 412984, 58610, '<td valign="top">I really like this. Everything is working together to create a wistful, mysterious mood. In this case the light obscures the truth - who these people are, and what they''re doing. Masterful.</td>', 'I really like this. Everything is working together to create a wistful, mysterious mood. In this case the light obscures the truth - who these people are, and what they''re doing. Masterful.', '2006-10-19 19:19:17.000000', NULL, 1),
(2944974, 410770, 58610, '<td valign="top">I was ready to report you for stealing someone else''s art when I finally got it - toast! This should be hanging on a gallery wall somewhere. Truely beautiful and inspirational work.</td>', 'I was ready to report you for stealing someone else''s art when I finally got it - toast! This should be hanging on a gallery wall somewhere. Truely beautiful and inspirational work.', '2006-10-19 19:22:36.000000', NULL, 1),
(2944985, 413197, 58610, '<td valign="top">I think  you could try cropping out the top 1/5 or so of the candle and burn in that bright spot on the candle''s surface. That would make it a winner in my opinion.</td>', 'I think  you could try cropping out the top 1/5 or so of the candle and burn in that bright spot on the candle''s surface. That would make it a winner in my opinion.', '2006-10-19 19:28:15.000000', NULL, 1),
(2945028, 411676, 58610, '<td valign="top">What are these? Really small leds? Insulators with lights inside? Very bold image. I like the way the background moves around the bulbs keeping the image from becoming static.</td>', 'What are these? Really small leds? Insulators with lights inside? Very bold image. I like the way the background moves around the bulbs keeping the image from becoming static.', '2006-10-19 19:43:39.000000', NULL, 1),
