(2948771, 411372, 66967, '<td valign="top">What a fantastic sky! Love the colors, silhouettes, and the sunbeams. Nice job!</td>', 'What a fantastic sky! Love the colors, silhouettes, and the sunbeams. Nice job!', '2006-10-21 10:42:13.000000', NULL, 1),
(2948816, 411318, 67412, '<td valign="top">Wonderful lighting, great reflection. Love it!</td>', 'Wonderful lighting, great reflection. Love it!', '2006-10-21 11:25:50.000000', NULL, 1),
