(2949243, 411555, 28742, '<td valign="top">This is spectacular! ...but I came from Planet X and THAT is not Planet X. Looks more like Planet W to the north. ;P</td>', 'This is spectacular! ...but I came from Planet X and THAT is not Planet X. Looks more like Planet W to the north. ;P', '2006-10-21 16:16:41.000000', NULL, 1),
(2949244, 412654, 28742, '<td valign="top">Don''t you mean Aurora Ribbonalis? ;-) ...seriously.</td>', 'Don''t you mean Aurora Ribbonalis? ;-) ...seriously.', '2006-10-21 16:17:27.000000', NULL, 1),
(2949248, 412041, 28742, '<td valign="top">This is fantastic! But everyone knows these types of shots don''t win ribbons.<br/> <br/>...oh wait, I was mistaken. These types of shots don''t NOT win ribbons. :)</td>', 'This is fantastic! But everyone knows these types of shots don''t win ribbons. ...oh wait, I was mistaken. These types of shots don''t NOT win ribbons. :)', '2006-10-21 16:19:29.000000', NULL, 1),
(2949250, 413266, 28742, '<td valign="top">I''ll go out on a limb and guess that those are fake eyelashes. ;-) <br/>Very cool. A little hot on the tip of the nose, but a very interesting, artistic image.</td>', 'I''ll go out on a limb and guess that those are fake eyelashes. ;-) Very cool. A little hot on the tip of the nose, but a very interesting, artistic image.', '2006-10-21 16:21:24.000000', NULL, 1),
(2949253, 413053, 28742, '<td valign="top">I am totally lost. This looks like a scene from Alien. Sorry, I stared at his thing much longer than any other and cannot figure out what I am looking at.</td>', 'I am totally lost. This looks like a scene from Alien. Sorry, I stared at his thing much longer than any other and cannot figure out what I am looking at.', '2006-10-21 16:24:54.000000', NULL, 1),
