(2954724, 411208, 66201, '<td valign="top">I think I understand what you were going for here: focus and light on the book as primary character in this picture: but I think that a greater depth of field would have been great: more focu to let the light do the talking. I love the tones and palette in this though.</td>', 'I think I understand what you were going for here: focus and light on the book as primary character in this picture: but I think that a greater depth of field would have been great: more focu to let the light do the talking. I love the tones and palette in this though.', '2006-10-23 15:12:10.000000', NULL, 1),
(2954727, 412929, 66201, '<td valign="top">I give this a 10: the picture has interest, patina, texture, a haunting atmosphere, a friendly character in the cat and fantastic use of natural honest light!!</td>', 'I give this a 10: the picture has interest, patina, texture, a haunting atmosphere, a friendly character in the cat and fantastic use of natural honest light!!', '2006-10-23 15:14:06.000000', NULL, 1),
