(2957058, 412833, 57229, '<td valign="top">Very nice. Maybe the green is just a little over-saturated, but the form composition captures the rhythm very well.</td>', 'Very nice. Maybe the green is just a little over-saturated, but the form composition captures the rhythm very well.', '2006-10-24 09:40:31.000000', NULL, 1),
(2957065, 410710, 57229, '<td valign="top">I could have used just a little more structure on the blank wall, maybe. All that pale space is just a little too dead. What the h*** though, it''s a great idea/vision and certainly effective</td>', 'I could have used just a little more structure on the blank wall, maybe. All that pale space is just a little too dead. What the h*** though, it''s a great idea/vision and certainly effective', '2006-10-24 09:43:54.000000', NULL, 1),
