(2957102, 413108, 15711, '<td valign="top">The play of light and shadow is superb. Almost like they are two separate entities, dancing in the light.  THe notes really make the shot for me. Nice.</td>', 'The play of light and shadow is superb. Almost like they are two separate entities, dancing in the light.  THe notes really make the shot for me. Nice.', '2006-10-24 09:59:30.000000', NULL, 1),
(2957103, 412929, 15711, '<td valign="top">MEOW. Love how diminished the kitty looks amidst the structure of the building.  Great lighting - oh, that was the point wasn''t it?</td>', 'MEOW. Love how diminished the kitty looks amidst the structure of the building.  Great lighting - oh, that was the point wasn''t it?', '2006-10-24 10:00:09.000000', NULL, 1),
(2957105, 410361, 15711, '<td valign="top">Something about this draws me in. Love the perfect profile of the dog against the building. All animal shots get an extra point from me. 8</td>', 'Something about this draws me in. Love the perfect profile of the dog against the building. All animal shots get an extra point from me. 8', '2006-10-24 10:00:44.000000', NULL, 1),
