(2957645, 413008, 50695, '<td valign="top">are you sure you didn''t get Cezanne to paint this? 8</td>', 'are you sure you didn''t get Cezanne to paint this? 8', '2006-10-24 14:05:04.000000', NULL, 1),
(2957650, 411500, 50695, '<td valign="top">I expect to see this on the cover of a science fiction magazine. 8</td>', 'I expect to see this on the cover of a science fiction magazine. 8', '2006-10-24 14:05:59.000000', NULL, 1),
