(2957695, 413335, 66543, '<td valign="top">The lighting is excellent.</td>', 'The lighting is excellent.', '2006-10-24 14:21:10.000000', NULL, 1),
(2957707, 411779, 58610, '<td valign="top">Contrast is a bit high. A tighter crop around the basket would improve the composition imo.</td>', 'Contrast is a bit high. A tighter crop around the basket would improve the composition imo.', '2006-10-24 14:27:40.000000', NULL, 1),
(2957710, 411060, 66543, '<td valign="top">The orange throughout does it for me.</td>', 'The orange throughout does it for me.', '2006-10-24 14:28:09.000000', NULL, 1),
(2957713, 412366, 58610, '<td valign="top">Good analogy. Nicely composed.</td>', 'Good analogy. Nicely composed.', '2006-10-24 14:28:49.000000', NULL, 1),
(2957716, 412984, 47916, '<td valign="top">Really beautiful shot!!  Well done!</td>', 'Really beautiful shot!!  Well done!', '2006-10-24 14:29:27.000000', NULL, 1),
(2957718, 412716, 58610, '<td valign="top">Here''s looking at you! Beautiful portrait.</td>', 'Here''s looking at you! Beautiful portrait.', '2006-10-24 14:30:08.000000', NULL, 1),
(2957722, 412399, 58610, '<td valign="top">Spooky! Beautifully exposed and composed.</td>', 'Spooky! Beautifully exposed and composed.', '2006-10-24 14:32:26.000000', NULL, 1),
(2957728, 413305, 58610, '<td valign="top">Wonderful exposure on the eyes. The soul comes through.You could be a little more careful on your masking around the face.</td>', 'Wonderful exposure on the eyes. The soul comes through.You could be a little more careful on your masking around the face.', '2006-10-24 14:35:06.000000', NULL, 1),
(2957732, 411295, 58610, '<td valign="top">I love the way you captured the raindrops in long exposure. The translusence of the mushrooms is incredible. I wish you could have used a different background.</td>', 'I love the way you captured the raindrops in long exposure. The translusence of the mushrooms is incredible. I wish you could have used a different background.', '2006-10-24 14:37:16.000000', NULL, 1),
