(2958427, 413071, 58610, '<td valign="top">Subtlety. Texture. Compostion. Content. Artistry. Meets challenge. 10. And, I want you to know that this is the first 10 I''ve voted as a member.</td>', 'Subtlety. Texture. Compostion. Content. Artistry. Meets challenge. 10. And, I want you to know that this is the first 10 I''ve voted as a member.', '2006-10-24 19:24:13.000000', NULL, 1),
