(2961176, 411407, 15711, '<td valign="top">Glad this did well.  Really a lovely image.</td>', 'Glad this did well.  Really a lovely image.', '2006-10-25 11:40:04.000000', NULL, 0),
(2961181, 412039, 14620, '<td valign="top">This is an incredibly lovely photo and the lighting has a lot to do with that.  Photos like this that just exude so much feeling are what makes me love photography so much.  Way to capture that moment. :)</td>', 'This is an incredibly lovely photo and the lighting has a lot to do with that.  Photos like this that just exude so much feeling are what makes me love photography so much.  Way to capture that moment. :)', '2006-10-25 11:41:44.000000', NULL, 0),
