(2962203, 411407, 20941, '<td valign="top">Just beautiful and so right for this challenge! Congrats on a top ten!</td>', 'Just beautiful and so right for this challenge! Congrats on a top ten!', '2006-10-25 16:51:10.000000', NULL, 0),
